// expect: exit 1
// screen: 0 Merit
// screen: 1 middle band
// screen: 2 exactly 72
int main(void)
{
    int mark = 72;
    cls();
    if (mark >= 80)
        puts("Distinction");
    else if (mark >= 60)
        puts("Merit");
    else if (mark >= 40)
        puts("Pass");
    else
        puts("Fail");
    if (mark > 50 && mark < 90)
        puts("middle band");
    if (mark == 72)
        puts("exactly 72");
    return mark > 50;
}
